import Foundation

/// Swift port of the web's `src/sync/doc.ts` (SyncDoc schema 1 and mergeDocs): the SAME JSON that the web app keeps in the person's Google Drive
/// appDataFolder (`slides-art-records.json`). Counts are kept per device (merge = larger count of each device, then summed), bests only improve,
/// history is a set. Golden vectors generated by the web code check that the results are identical (`ios/scripts/export-drive.ts`).
public struct DriveDoc: Codable, Equatable, Sendable {
    /// 2 adds `favorites`. An app that only knows schema 1 sees 2 as newer and leaves the file alone, so it can never wipe the favourites.
    public static let schemaVersion = 2
    public static let historyLimit = 200
    static let maxRecords = 6000

    public struct Best: Codable, Equatable, Sendable { public var timeMs: Int?; public var moves: Int?
        public init(timeMs: Int? = nil, moves: Int? = nil) { self.timeMs = timeMs; self.moves = moves } }
    public struct KeyRecord: Codable, Equatable, Sendable {
        public var bestTimeMs: Int?; public var bestMoves: Int?; public var lastClearedAt: Int?
        public var clears: [String: Int]
        public init(bestTimeMs: Int? = nil, bestMoves: Int? = nil, lastClearedAt: Int? = nil, clears: [String: Int] = [:]) { self.bestTimeMs = bestTimeMs; self.bestMoves = bestMoves; self.lastClearedAt = lastClearedAt; self.clears = clears }
    }
    public struct Daily: Codable, Equatable, Sendable { public var number: Int; public var artworkId: String; public var timeMs: Int; public var moves: Int
        public init(number: Int, artworkId: String, timeMs: Int, moves: Int) { self.number = number; self.artworkId = artworkId; self.timeMs = timeMs; self.moves = moves } }
    public struct History: Codable, Equatable, Sendable { public var date: String; public var mode: ArtPuzzle.Mode; public var size: Int; public var artworkId: String; public var timeMs: Int; public var moves: Int
        public init(date: String, mode: ArtPuzzle.Mode, size: Int, artworkId: String, timeMs: Int, moves: Int) { self.date = date; self.mode = mode; self.size = size; self.artworkId = artworkId; self.timeMs = timeMs; self.moves = moves } }

    public var schema = DriveDoc.schemaVersion
    public var counters: [String: Int] = [:]
    public var bests: [String: Best] = [:]
    public var records: [String: KeyRecord] = [:]
    public var dailyHistory: [String: Daily] = [:]
    public var history: [History] = []
    /// Starred paintings by artwork id; a later change wins, at the same instant "on" wins.
    public var favorites: [String: ArtFavorite] = [:]
    public init() {}

    enum K: String, CodingKey { case schema, counters, bests, records, dailyHistory, history, favorites }
    /// A document without `favorites` (written by a schema-1 app) decodes with none.
    public init(from d: Decoder) throws {
        let c = try d.container(keyedBy: K.self)
        schema = try c.decodeIfPresent(Int.self, forKey: .schema) ?? DriveDoc.schemaVersion
        counters = try c.decodeIfPresent([String: Int].self, forKey: .counters) ?? [:]
        bests = try c.decodeIfPresent([String: Best].self, forKey: .bests) ?? [:]
        records = try c.decodeIfPresent([String: KeyRecord].self, forKey: .records) ?? [:]
        dailyHistory = try c.decodeIfPresent([String: Daily].self, forKey: .dailyHistory) ?? [:]
        history = try c.decodeIfPresent([History].self, forKey: .history) ?? []
        favorites = try c.decodeIfPresent([String: ArtFavorite].self, forKey: .favorites) ?? [:]
    }

    public var totalClears: Int { counters.values.reduce(0, +) }

    /// The JSON text that goes into the Drive file (sorted keys: stable).
    public func jsonString() -> String {
        let e = JSONEncoder(); e.outputFormatting = [.sortedKeys]
        return (try? e.encode(self)).flatMap { String(data: $0, encoding: .utf8) } ?? "{}"
    }
    public func jsonData() -> Data { Data(jsonString().utf8) }

    // MARK: merge (port of mergeDocs)

    private static func minDef(_ a: Int?, _ b: Int?) -> Int? { a == nil ? b : (b == nil ? a : min(a!, b!)) }
    private static func maxDef(_ a: Int?, _ b: Int?) -> Int? { a == nil ? b : (b == nil ? a : max(a!, b!)) }
    private static func maxMap(_ a: [String: Int], _ b: [String: Int]) -> [String: Int] {
        var out = a
        for (k, v) in b { out[k] = max(out[k] ?? 0, v) }
        return out
    }
    static func histKey(_ h: History) -> String { "\(h.date)|\(h.mode.rawValue)|\(h.size)|\(h.artworkId)|\(h.timeMs)|\(h.moves)" }

    public static func merge(_ a: DriveDoc, _ b: DriveDoc) -> DriveDoc {
        var out = DriveDoc()
        out.schema = max(a.schema, b.schema)
        out.counters = maxMap(a.counters, b.counters)
        for k in Set(a.bests.keys).union(b.bests.keys) {
            out.bests[k] = Best(timeMs: minDef(a.bests[k]?.timeMs, b.bests[k]?.timeMs), moves: minDef(a.bests[k]?.moves, b.bests[k]?.moves))
        }
        for k in Set(a.records.keys).union(b.records.keys) {
            let x = a.records[k], y = b.records[k]
            out.records[k] = KeyRecord(bestTimeMs: minDef(x?.bestTimeMs, y?.bestTimeMs), bestMoves: minDef(x?.bestMoves, y?.bestMoves),
                                       lastClearedAt: maxDef(x?.lastClearedAt, y?.lastClearedAt), clears: maxMap(x?.clears ?? [:], y?.clears ?? [:]))
        }
        for k in Set(a.dailyHistory.keys).union(b.dailyHistory.keys) {
            let x = a.dailyHistory[k], y = b.dailyHistory[k]
            if let x, let y {
                if x.artworkId != y.artworkId { out.dailyHistory[k] = WebCollation.compare(x.artworkId, y.artworkId) <= 0 ? x : y }
                else if x.timeMs != y.timeMs { out.dailyHistory[k] = x.timeMs < y.timeMs ? x : y }
                else { out.dailyHistory[k] = x.moves <= y.moves ? x : y }
            } else { out.dailyHistory[k] = x ?? y }
        }
        var seen: [String: History] = [:]
        for h in a.history + b.history { seen[histKey(h)] = h }
        let sorted = seen.values.sorted { WebCollation.compare(histKey($0), histKey($1)) < 0 }
        out.history = Array(sorted.suffix(historyLimit))
        for k in Set(a.favorites.keys).union(b.favorites.keys) {
            let x = a.favorites[k], y = b.favorites[k]
            if let x, let y { out.favorites[k] = x.at != y.at ? (x.at > y.at ? x : y) : (x.on ? x : y) } else { out.favorites[k] = x ?? y }
        }
        return out
    }

    // MARK: reading what came from Drive (port of normalizeDoc): never trusted blindly

    public enum ReadError: Error, Equatable { case newerSchema, unreadable }

    /// Throws `.newerSchema` when written by a newer app and `.unreadable` for anything that is not a records document: nothing may then be overwritten.
    public static func parse(_ data: Data) throws -> DriveDoc {
        guard let raw = try? JSONSerialization.jsonObject(with: data, options: [.fragmentsAllowed]) else { throw ReadError.unreadable }
        return try normalize(raw)
    }

    public static func normalize(_ raw: Any) throws -> DriveDoc {
        guard let o = raw as? [String: Any] else { throw ReadError.unreadable }
        guard let schema = num(o["schema"], max: 1e15) else { throw ReadError.unreadable } // JS: any number; checked below
        if let rawSchema = (o["schema"] as? NSNumber)?.doubleValue, rawSchema > Double(schemaVersion) { throw ReadError.newerSchema }
        guard schema >= 1 else { throw ReadError.unreadable }
        var d = DriveDoc()
        d.counters = cleanCounts(o["counters"])
        if let bests = o["bests"] as? [String: Any] {
            for (k, v) in bests where matches(k, digitsMax: 2) {
                guard let b = v as? [String: Any] else { continue }
                d.bests[k] = Best(timeMs: num(b["timeMs"]), moves: num(b["moves"]))
            }
        }
        if let recs = o["records"] as? [String: Any] {
            for (k, v) in recs.sorted(by: { $0.key < $1.key }).prefix(maxRecords) where validRecordKey(k) {
                guard let r = v as? [String: Any] else { continue }
                d.records[k] = KeyRecord(bestTimeMs: num(r["bestTimeMs"]), bestMoves: num(r["bestMoves"]), lastClearedAt: num(r["lastClearedAt"], max: 1e14), clears: cleanCounts(r["clears"]))
            }
        }
        if let days = o["dailyHistory"] as? [String: Any] {
            for (k, v) in days where validDate(k) {
                guard let e = v as? [String: Any], let art = idStr(e["artworkId"]), let t = num(e["timeMs"]), let m = num(e["moves"]) else { continue }
                d.dailyHistory[k] = Daily(number: num(e["number"]) ?? 0, artworkId: art, timeMs: t, moves: m)
            }
        }
        if let hist = o["history"] as? [Any] {
            for item in hist.suffix(historyLimit * 2) {
                guard let h = item as? [String: Any], let art = idStr(h["artworkId"]), let t = num(h["timeMs"]), let m = num(h["moves"]), let s = num(h["size"], max: 20),
                      let date = h["date"] as? String, validDate(date), let modeS = h["mode"] as? String, let mode = ArtPuzzle.Mode(rawValue: modeS) else { continue }
                d.history.append(History(date: date, mode: mode, size: s, artworkId: art, timeMs: t, moves: m))
            }
            d.history = Array(d.history.suffix(historyLimit))
        }
        if let favs = o["favorites"] as? [String: Any] {
            for (k, v) in favs.sorted(by: { $0.key < $1.key }).prefix(maxRecords) {
                guard let id = idStr(k, max: 120), let f = v as? [String: Any], let on = f["on"] as? NSNumber, isBool(on) else { continue }
                d.favorites[id] = ArtFavorite(on: on.boolValue, at: num(f["at"], max: 1e14) ?? 0)
            }
        }
        return d
    }

    private static func isBool(_ v: Any) -> Bool { if let n = v as? NSNumber { return CFGetTypeID(n) == CFBooleanGetTypeID() }; return false }
    private static func num(_ v: Any?, max: Double = 1e9) -> Int? {
        guard let v, !isBool(v), let n = v as? NSNumber else { return nil }
        let x = n.doubleValue
        guard x.isFinite, x >= 0, x <= max else { return nil }
        return Int(x.rounded(.toNearestOrAwayFromZero))
    }
    private static func idChar(_ c: UInt8) -> Bool { (c >= 48 && c <= 57) || (c >= 65 && c <= 90) || (c >= 97 && c <= 122) || c == 95 || c == 46 || c == 58 || c == 124 || c == 45 }
    private static func idStr(_ v: Any?, max: Int = 80) -> String? {
        guard let s = v as? String, !s.isEmpty, s.utf16.count <= max, s.utf8.allSatisfy(idChar) else { return nil }
        return s
    }
    private static func cleanCounts(_ v: Any?) -> [String: Int] {
        var out: [String: Int] = [:]
        guard let o = v as? [String: Any] else { return out }
        for (k, n) in o { if let id = idStr(k), let c = num(n, max: 1e7) { out[id] = c } }
        return out
    }
    private static func matches(_ s: String, digitsMax: Int) -> Bool { !s.isEmpty && s.utf8.count <= digitsMax && s.utf8.allSatisfy { $0 >= 48 && $0 <= 57 } }
    private static func validRecordKey(_ k: String) -> Bool {
        let parts = k.split(separator: ":", omittingEmptySubsequences: false)
        guard parts.count == 2, matches(String(parts[1]), digitsMax: 2), (1...80).contains(parts[0].utf8.count) else { return false }
        return parts[0].utf8.allSatisfy { ($0 >= 48 && $0 <= 57) || ($0 >= 65 && $0 <= 90) || ($0 >= 97 && $0 <= 122) || $0 == 95 || $0 == 45 }
    }
    private static func validDate(_ s: String) -> Bool { SyncRules.validDate(s) }
}

/// What JavaScript's `localeCompare` (ICU root collation) does for the characters ids and history keys are made of:
/// punctuation `_ - : . |` first, then digits, then letters (case-insensitive first, lowercase before uppercase on a tie).
enum WebCollation {
    private static func primary(_ c: Character) -> Int {
        switch c {
        case "_": return 1
        case "-": return 2
        case ":": return 3
        case ".": return 4
        case "|": return 5
        case "0"..."9": return 10 + Int(c.asciiValue! - 48)
        case "a"..."z": return 30 + Int(c.asciiValue! - 97)
        case "A"..."Z": return 30 + Int(c.asciiValue! - 65)
        default: return 1000 + Int(c.unicodeScalars.first!.value)
        }
    }
    static func compare(_ a: String, _ b: String) -> Int {
        let x = Array(a), y = Array(b)
        for i in 0..<min(x.count, y.count) {
            let p = primary(x[i]), q = primary(y[i])
            if p != q { return p < q ? -1 : 1 }
        }
        if x.count != y.count { return x.count < y.count ? -1 : 1 }
        for i in 0..<x.count where x[i] != y[i] { return x[i].isLowercase ? -1 : 1 } // tertiary: lowercase first
        return 0
    }
}
